/* ------------------------------------------------------------ geometry -- */
const GEO = {
  SIZE: 160,
  PANEL_X: 21, PANEL_W: 118, PANEL_Y: 8, PANEL_R: 10,
  CARD_X: 11, CARD_W: 138, CARD_Y: 24, CARD_H: 27, CARD_R: 8,
  MED_CX: 80, MED_CY: 33, MED_R: 14,
  FADE_A: 0.7, FADE_B: 0.82,
  PAD: 10,
  CPAD: 8,
};

/* ------------------------------------------------------------- presets -- */
/* A preset is a set of token values plus the dials it moves: stroke width,
   corner language, elevation, and the literal tile colors. Nothing else in
   the language changes, which is what lets one engine serve both looks. */

const PRESETS = {
  soft: {
    label: 'Soft Layered',
    note: 'The exploration\'s own preset. Warm neutral, layered depth, a fade out edge.',
    sw: 0.5, radius: 1, elevation: 'lift',
    brand: ['#C25E3E', '#2F9468', '#5C82CE', '#B08A3E', '#8A6BC0'],
    light: {
      canvas: '#EDEAE6', ghost: '#EAE7E2', panel: '#F7F5F2', 'panel-top': '#FCFBF9',
      line: '#B9B1A4', surface: '#FFFFFF', stroke: '#35322D', 'stroke-soft': '#9B948A',
      fill: '#DCD6CE', 'fill-soft': '#E9E4DC', accent: '#3E9077',
      'shadow-c': '#4A3F33', 'shadow-o': '0.16',
    },
    dark: {
      canvas: '#1A1918', ghost: '#1F1E1C', panel: '#262523', 'panel-top': '#2E2C29',
      line: '#5C564D', surface: '#322F2B', stroke: '#DDD9D3', 'stroke-soft': '#877F74',
      fill: '#4A463E', 'fill-soft': '#35322D', accent: '#5FB694',
      'shadow-c': '#000000', 'shadow-o': '0.55',
    },
  },
  windows: {
    label: 'Windows',
    note: 'Derived from the 72 illustrations in the library: cool neutrals and Windows blue. '
      + 'A proposal grounded in what recurs, not a match for the shipped set.',
    /* The corner dial stays at 1. The set's real rule is proportional, half of
       every rounded rect sitting at a sixth of its short side, and a multiplier
       on absolute radii cannot express that: a sixth of the card's short side
       is 4.5 while a sixth of the panel's is nearly 20. The language's own
       absolute radii already fall between those two, so moving the multiplier
       would trade one wrong answer for another. Proportional corners want a
       dial the preset does not have. */
    sw: 0.5, radius: 1, elevation: 'lift',
    /* Five measured hues from the set, far enough apart to read as different
       services rather than as a ramp. */
    brand: ['#0078D4', '#FD6F03', '#81B93A', '#5B41D3', '#222E48'],
    /* Measured, unless marked. 72 illustrations carry 238 distinct colors and
       no shared palette, so these are the values that actually recur rather
       than an average of the set, which would be an average of noise.
       Every mid and dark neutral in the set is cool: blue runs 8 to 28 points
       above red. The bars are the deliberate exception, true gray while the
       surfaces are cool, so they read as content rather than as chrome. */
    light: {
      canvas: '#ECECEC',        // derived: #F0F0F0 is measured but too close to the
                                // panel, and canvas to panel has to be visible
                                // rather than a whisper or nothing separates at
                                // display size. This matches the step the
                                // exploration's own preset uses.
      ghost: '#E7E7E7',         // 3 files. Sits barely below canvas, behind the panel
      panel: '#F5F5F5',         // 37 files, the most used color in the set
      'panel-top': '#FCFCFC',   // derived: about 2% above panel
      line: '#A8B5BF',          // 4 files. Cool, and reads on canvas, panel and a white card
      surface: '#FFFFFF',
      stroke: '#1E2021',        // 3 files. The only genuinely dark value
      'stroke-soft': '#8897A4', // 4 files. Cool, about halfway to the panel
      fill: '#E2E2E2',          // derived: true gray on purpose, against the cool surfaces
      'fill-soft': '#EDEDED',   // derived
      accent: '#0078D4',        // 13 files
      'shadow-c': '#000000',
      'shadow-o': '0.10',
    },
    /* Derived. Nothing in the library ships a dark variant, so there was
       nothing to measure: every value below keeps the light set's cool cast
       and the language's rule that a surface gets lighter as it comes
       forward. Blue stays within a few points of green on every dark surface,
       which is what stops a cool near-black drifting olive as it lightens. */
    dark: {
      canvas: '#1B1D1F', ghost: '#202325', panel: '#26292C', 'panel-top': '#2E3135',
      line: '#4A5057', surface: '#34383C', stroke: '#F2F4F5', 'stroke-soft': '#8E9AA6',
      fill: '#434649', 'fill-soft': '#323538', accent: '#4CC2FF',
      'shadow-c': '#000000', 'shadow-o': '0.50',
    },
  },
  flat: {
    label: 'Flat outline',
    note: 'No shadow at all. Everything separates on the line and the fills, which is the honest test of whether the composition works.',
    sw: 0.5, radius: 1.2, elevation: 'flat',
    brand: ['#0078D4', '#107C10', '#8764B8', '#C239B3', '#CA5010'],
    light: {
      canvas: '#FFFFFF', ghost: '#F4F4F4', panel: '#FFFFFF', 'panel-top': '#FFFFFF',
      line: '#B3B3B3', surface: '#FFFFFF', stroke: '#1B1B1B', 'stroke-soft': '#8A8A8A',
      fill: '#E4E4E4', 'fill-soft': '#F0F0F0', accent: '#0078D4',
      'shadow-c': '#000000', 'shadow-o': '0',
    },
    dark: {
      canvas: '#1A1A1A', ghost: '#232323', panel: '#1A1A1A', 'panel-top': '#1A1A1A',
      line: '#525252', surface: '#1A1A1A', stroke: '#F2F2F2', 'stroke-soft': '#9A9A9A',
      fill: '#3C3C3C', 'fill-soft': '#2C2C2C', accent: '#4CC2FF',
      'shadow-c': '#000000', 'shadow-o': '0',
    },
  },
};

/* The live style. Reassigned before every build rather than read through a
   function, so the layout code below stays readable. */
let P = PRESETS.soft;
let SW = 0.5, RR = 1;
/* Set while building a composition that will be nested into a device screen. A
   screen is emissive: a drop shadow inside one reads as dirt, and the device
   body is already the one element casting. */
let FLAT_OVERRIDE = false;
const flatNow = () => FLAT_OVERRIDE || P.elevation === 'flat';
let LINE, FILL, FSOFT, SOFT, SURF, GHOST, STRK, ACC, BRAND;

function applyPreset(key, accentHex) {
  P = PRESETS[key] || PRESETS.soft;
  SW = P.sw;
  RR = P.radius;
  const t = (n) => `var(--il-${n}, ${P.light[n]})`;
  LINE = t('line'); FILL = t('fill'); FSOFT = t('fill-soft'); SOFT = t('stroke-soft');
  SURF = t('surface'); GHOST = t('ghost'); STRK = t('stroke');
  ACC = `var(--il-accent, ${accentHex || P.light.accent})`;
  BRAND = P.brand;
}

const cssVars = (preset, theme, accent) => {
  const src = PRESETS[preset][theme];
  const out = {};
  Object.keys(src).forEach((k) => { out['--il-' + k] = src[k]; });
  if (accent) out['--il-accent'] = accent;
  return out;
};

const n1 = (v) => Number(v).toFixed(1);
const n2 = (v) => Number(v).toFixed(2);
/* Radii scale with the preset's corner language, never past a half side. */
const rad = (r, w, h) => {
  let v = r * RR;
  if (w !== undefined) v = Math.min(v, w / 2);
  if (h !== undefined) v = Math.min(v, h / 2);
  return Number(v.toFixed(2));
};

/* --------------------------------------------------------------- guards -- */
/* Three defect classes that shipped in the exploration before anyone noticed
   them: a glyph overlapping the neighbors it sits between, a rail protruding
   past its first node, and a card whose content touches its own bottom edge.
   Here they throw, and the bench shows the throw instead of the illustration. */
const CLEARANCE = 2.0;

function fits(x0, x1, size, what) {
  const room = x1 - x0;
  if (size + 2 * CLEARANCE > room) {
    throw new Error(`${what || 'glyph'} is ${size} wide and needs ${size + 2 * CLEARANCE} of ` +
      `room, but the gap ${x0}..${x1} is only ${room}.`);
  }
  return x0 + (room - size) / 2;
}

function padded(cardY, cardH, top, bottom, what) {
  const t = top - cardY;
  const b = (cardY + cardH) - bottom;
  if (b <= 0) throw new Error(`${what}: content overflows the bottom by ${(-b).toFixed(1)}.`);
  if (Math.abs(t - b) > 4) throw new Error(`${what}: padding is ${t.toFixed(1)} top vs ${b.toFixed(1)} bottom.`);
  return true;
}

/* ---------------------------------------------------------------- icons -- */
/* One namespace: every glyph is an Expressive Assets asset id. CORE holds the
   baked paths so the page draws before any fetch; LIB and PARTS fill in from
   manifest.json and from Mason's own pieces. */

const LIB = { loaded: false, sys: [], illos: [], paths: new Map(), status: 'Library not loaded yet' };
const PARTS = { loaded: false, list: [], paths: new Map(), status: 'No parts file' };

function iconPath(id) {
  if (!id) return null;
  if (id.startsWith('part:')) return PARTS.paths.get(id.slice(5)) || null;
  const short = id.startsWith('system.') ? id.slice(7) : id;
  if (CORE[short]) return CORE[short];
  return LIB.paths.get(id) || null;
}

function icon(id, x, y, size, color) {
  const p = iconPath(id);
  if (!p) return '';
  const sc = size / p.grid;
  return `<g transform="translate(${n2(x)} ${n2(y)}) scale(${sc.toFixed(5)})" fill="${color || STRK}">` +
    `<path d="${p.d}"/></g>`;
}

/* A slot is a named position that art can be bound to. The layout names the
   slot and supplies the default; Pieces mode rebinds it. This is the only way
   library art gets into a composition, which is what keeps it on rails. */
function slot(o, key, fallback, x, y, size, color) {
  const bound = o.slots && o.slots[key];
  return icon(bound || fallback, x, y, size, color);
}

const avatar = (o, x, y, size, color) =>
  slot(o, 'avatar', 'system.person-circle', x, y, size, color || SOFT);

/* ----------------------------------------------------------- primitives -- */
function bar(x, y, w, h, fill) {
  h = h === undefined ? 5 : h;
  return `<rect x="${n1(x)}" y="${n1(y)}" width="${n1(w)}" height="${n1(h)}" rx="${n2(h / 2)}" fill="${fill || FILL}"/>`;
}

function barpair(x, y, w1, w2, h1, h2, gap) {
  h1 = h1 === undefined ? 4.2 : h1;
  h2 = h2 === undefined ? 5.2 : h2;
  gap = gap === undefined ? 7.6 : gap;
  return bar(x, y, w1, h1) + bar(x, y + gap, w2, h2);
}

function dot(x, y, r, on, c) {
  if (on === undefined) on = true;
  return on
    ? `<circle cx="${n1(x)}" cy="${n1(y)}" r="${r}" fill="${c || FILL}"/>`
    : `<circle cx="${n1(x)}" cy="${n1(y)}" r="${r}" fill="none" stroke="${LINE}" stroke-width="${SW}"/>`;
}

/* Separators are filled hairlines, not strokes. That is what keeps the stroke
   inventory at exactly one width and one color. */
const rule = (x1, x2, y, op) =>
  `<rect x="${x1}" y="${y}" width="${x2 - x1}" height="${SW}" fill="${LINE}" opacity="${op === undefined ? 0.8 : op}"/>`;
const vrule = (x, y1, y2, op) =>
  `<rect x="${x}" y="${y1}" width="${SW}" height="${y2 - y1}" fill="${LINE}" opacity="${op === undefined ? 0.75 : op}"/>`;

/* What sits behind the panel. Optional, and varied on purpose: a fixed plate
   behind every illustration is the fastest way to make a set look mechanical. */
function backdrop(kind, x, w, y, h) {
  const H = h === undefined || h === null ? 160 - y : h;
  if (kind === 'none') return '';
  if (kind === 'plate') {
    return `<rect x="${x - 7}" y="${y + 4}" width="${w + 14}" height="${H + 6}" rx="${rad(GEO.PANEL_R + 6)}" ` +
      `fill="${GHOST}" stroke="${LINE}" stroke-width="${SW}"/>`;
  }
  if (kind === 'offset') {
    return `<rect x="${x + 8}" y="${y + 8}" width="${w}" height="${H}" rx="${rad(GEO.PANEL_R)}" ` +
      `fill="${GHOST}" stroke="${LINE}" stroke-width="${SW}"/>`;
  }
  if (kind === 'twin') {
    // Every sheet steps down from the one in front, and no two share a top
    // edge, because the front card has to read as the front card.
    return [10, 5].map((d) =>
      `<rect x="${x - d}" y="${y + d}" width="${w + 2 * d}" height="${H}" rx="${rad(GEO.PANEL_R + Math.floor(d / 2))}" ` +
      `fill="${GHOST}" stroke="${LINE}" stroke-width="${SW}"/>`).join('');
  }
  throw new Error('unknown backdrop ' + kind);
}

/* mode 'fade' is open at the bottom and dissolves: there is more.
   mode 'contained' is closed on all four sides: this is all of it. */
function panel(uid, x, w, y, h, mode, chrome, back) {
  x = x === undefined ? 21 : x; w = w === undefined ? 118 : w; y = y === undefined ? 8 : y;
  mode = mode || 'fade'; back = back === undefined ? 'plate' : back;
  const r = rad(GEO.PANEL_R);
  let s = backdrop(back, x, w, y, h);
  if (mode === 'fade') {
    s += `<path d="M${x} ${y + r}a${r} ${r} 0 0 1 ${r} -${r}h${n2(w - 2 * r)}a${r} ${r} 0 0 1 ${r} ${r}V160H${x}z" ` +
      `fill="url(#panelG-${uid})" stroke="${LINE}" stroke-width="${SW}"/>`;
  } else {
    s += `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${r}" ` +
      `fill="url(#panelG-${uid})" stroke="${LINE}" stroke-width="${SW}"/>`;
  }
  if (chrome) {
    for (let i = 0; i < 3; i++) s += dot(x + 10 + i * 5.5, y + 9, 1.7, true, LINE);
    s += rule(x, x + w, y + 16, 0.55);
  }
  return s;
}

function card(x, y, w, h, r, uid, lift, fill, stroke) {
  if (lift === undefined) lift = true;
  if (flatNow()) lift = false;
  // Bigger objects sit further off the surface. One shadow for everything reads
  // as a sticker sheet rather than a stack.
  const big = w * h > 2600;
  const f = lift ? ` filter="url(#lift${big ? 'L' : ''}-${uid})"` : '';
  return `<g${f}><rect x="${n1(x)}" y="${n1(y)}" width="${n1(w)}" height="${n1(h)}" rx="${rad(r, w, h)}" ` +
    `fill="${fill || SURF}" stroke="${stroke || LINE}" stroke-width="${SW}"/></g>`;
}

/* A tile is a colored square, or an outlined square holding bound art. */
function tile(o, x, y, s, r, fill) {
  s = s === undefined ? 16 : s; r = r === undefined ? 5 : r;
  const bound = o && o.slots && o.slots.tile;
  if (bound) {
    const g = s * 0.68;
    return `<rect x="${x}" y="${y}" width="${s}" height="${s}" rx="${rad(r, s, s)}" fill="none" ` +
      `stroke="${LINE}" stroke-width="${SW}"/>` +
      icon(bound, x + (s - g) / 2, y + (s - g) / 2, g, SOFT);
  }
  if (fill) return `<rect x="${x}" y="${y}" width="${s}" height="${s}" rx="${rad(r, s, s)}" fill="${fill}"/>`;
  return `<rect x="${x}" y="${y}" width="${s}" height="${s}" rx="${rad(r, s, s)}" fill="none" ` +
    `stroke="${LINE}" stroke-width="${SW}"/>` + dot(x + s / 2, y + s / 2, 2.4);
}

const kebab = (x, y) => [-1, 0, 1].map((i) => dot(x, y + i * 3.6, 1.15, true, SOFT)).join('');
const check = (x, y, s, c) => icon('system.checkmark', x, y, s === undefined ? 9 : s, c || ACC);

/* A row of avatars plus a +N chip. Deliberately spaced rather than overlapped:
   an overlapping cluster needs a surface-colored knockout ring to stay
   legible, and that would be a second stroke color in a system that has one. */
function cluster(x, y, cols, r) {
  r = r === undefined ? 6.2 : r;
  const gap = r * 2 + 2.4;
  let s = cols.map((c, i) =>
    `<circle cx="${n1(x + i * gap)}" cy="${y}" r="${r}" fill="${c}" opacity="0.7"/>`).join('');
  const cx = x + cols.length * gap;
  s += `<circle cx="${n1(cx)}" cy="${y}" r="${r}" fill="${FSOFT}"/>`;
  return s + bar(cx - 3.2, y - 1.4, 6.4, 2.8, SOFT);
}

/* Selected pills are a fill; unselected are an outline. One stroke spec. */
function pill(x, y, w, h, sel) {
  h = h === undefined ? 11 : h;
  const edge = sel ? '' : ` stroke="${LINE}" stroke-width="${SW}"`;
  return `<rect x="${n1(x)}" y="${y}" width="${n1(w)}" height="${h}" rx="${h / 2}" ` +
    `fill="${sel ? FSOFT : 'none'}"${edge}/>`;
}

/* A vertical rail through a set of nodes. Starts at the FIRST node's center so
   the node caps it: a rail beginning above its first dot leaves a visible stub.
   It may run past the last node, and that tail is what says "and more". */
function rail(x, ys, r, tail) {
  r = r === undefined ? 3.6 : r; tail = tail === undefined ? 22 : tail;
  let s = vrule(x, ys[0], ys[ys.length - 1] + tail, 0.7);
  ys.forEach((y, i) => { s += dot(x, y, r, true, i === 0 ? ACC : FILL); });
  return s;
}

function headerCard(uid, o, ic, x, w, y, h) {
  x = x === undefined ? 11 : x; w = w === undefined ? 138 : w;
  y = y === undefined ? GEO.CARD_Y : y; h = h === undefined ? GEO.CARD_H : h;
  const pairH = 8.4 + 6;  // gap plus the lower bar: the pair's real height
  padded(y, h, y + (h - pairH) / 2, y + (h + pairH) / 2, 'header card');
  return card(x, y, w, h, GEO.CARD_R, uid)
    + slot(o, 'feature', ic, x + 16, y + (h - 16) / 2, 16)
    + barpair(x + 41, y + (h - pairH) / 2, 29, 58, 4.8, 6, 8.4);
}

function medallion(uid, o, ic, cx, cy, r, lift) {
  cx = cx === undefined ? 80 : cx;
  cy = cy === undefined ? GEO.MED_CY : cy;
  r = r === undefined ? GEO.MED_R : r;
  if (flatNow()) lift = false;
  const f = lift ? ` filter="url(#lift-${uid})"` : '';
  return `<g${f}><circle cx="${cx}" cy="${cy}" r="${r}" fill="${SURF}" ` +
    `stroke="${LINE}" stroke-width="${SW}"/></g>` + slot(o, 'feature', ic, cx - 7.5, cy - 7.5, 15);
}

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;')
  .replace(/>/g, '&gt;').replace(/"/g, '&quot;');

/* Every id carries the illustration's own suffix. Gradient and mask ids are
   document-global, so two copies sharing ids make the second paint with the
   first's gradient: the dark preview came out white the first time this ran,
   and the contact sheet, the size ladder and a device screen all depend on
   this being right. */
function doc(uid, label, faded, floating, opts) {
  const contained = !!(opts && opts.contained);
  const fadeDefs = contained ? '' : `
    <linearGradient id="fadeG-${uid}" x1="0" y1="0" x2="0" y2="1">
      <stop offset="${GEO.FADE_A}" stop-color="#fff"/><stop offset="${GEO.FADE_B}" stop-color="#000"/>
    </linearGradient>
    <mask id="fade-${uid}"><rect width="160" height="160" fill="url(#fadeG-${uid})"/></mask>`;
  const shadowDefs = flatNow() ? '' : `
    <filter id="lift-${uid}" x="-60%" y="-60%" width="220%" height="220%">
      <feDropShadow dx="0" dy="2" stdDeviation="2.6"
        flood-color="var(--il-shadow-c, ${P.light['shadow-c']})" flood-opacity="var(--il-shadow-o, ${P.light['shadow-o']})"/>
    </filter>
    <filter id="liftL-${uid}" x="-60%" y="-60%" width="220%" height="220%">
      <feDropShadow dx="0" dy="4" stdDeviation="5"
        flood-color="var(--il-shadow-c, ${P.light['shadow-c']})" flood-opacity="var(--il-shadow-o, ${P.light['shadow-o']})"/>
    </filter>`;
  const body = contained
    ? faded + '\n' + (floating || '')
    : `  <g mask="url(#fade-${uid})">\n${faded}\n  </g>\n${floating || ''}`;
  return `<svg viewBox="0 0 160 160" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${esc(label)}" class="il">
  <defs>${fadeDefs}
    <linearGradient id="panelG-${uid}" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="var(--il-panel-top, ${P.light['panel-top']})"/>
      <stop offset="1" stop-color="var(--il-panel, ${P.light.panel})"/>
    </linearGradient>${shadowDefs}
  </defs>
${body}
</svg>
`;
}

/* ======================================================= L A Y O U T S == */
/* Each layout sizes its own panel to its own content and picks an edge
   treatment. Only the language is shared. `rows` is the one thing a caller may
   vary, and only downward: the fade line at y 112 sets the ceiling. */

function L1(uid, label, ic, o) {
  let b = panel(uid, 21, 118, 8, null, 'fade', false, 'twin');
  for (let i = 0; i < o.rows; i++) {
    const y = 60 + i * 21;
    b += avatar(o, 33, y, 15);
    b += barpair(57, y + 0.5, 28, 52, 4.2, 5.2, 7.4);
  }
  return doc(uid, label, b, headerCard(uid, o, ic));
}

/* Narrow panel, wide raised row. The float is the widest thing here. */
function L2(uid, label, ic, o) {
  let b = panel(uid, 25, 110, 8, null, 'fade', false, 'offset');
  [[35, 90, 16, 0.70], [45, 70, 13, 0.40]].forEach(([x, w, h, op], i) => {
    const y = 84 + i * 22;
    b += `<g opacity="${op}">` + card(x, y, w, h, 6.5, uid, false);
    b += avatar(o, x + 7, y + h / 2 - 5, 10);
    b += bar(x + 21, y + h / 2 - 2.1, w - 38, 4.2);
    b += slot(o, 'action', 'system.edit', x + w - 15, y + h / 2 - 4.5, 9, SOFT) + '</g>';
  });
  let top = card(13, 56, 134, 21, 7, uid);
  top += avatar(o, 24, 61.5, 11) + bar(41, 64.7, 62, 4.6);
  top += slot(o, 'action', 'system.edit', 129, 61.5, 10, SOFT);
  return doc(uid, label, b, medallion(uid, o, ic) + top);
}

function L3(uid, label, ic, o) {
  let b = panel(uid, 24, 112, 8, null, 'fade', false, 'plate');
  for (let i = 0; i < o.rows; i++) {
    const y = 62 + i * 22;
    b += slot(o, 'row', 'system.book-open', 34, y, 13, SOFT);
    b += barpair(54, y - 0.5, 30, 54, 4.2, 5.2, 7.4);
  }
  const y = GEO.CARD_Y;
  let f = card(11, y, 138, 24, 8, uid) + slot(o, 'feature', ic, 21, y + 5.5, 13, SOFT);
  const xs = [40, 66, 96, 120], ws = [22, 26, 20, 18];
  const sel = o.sel === undefined ? 1 : o.sel;
  xs.forEach((x, i) => {
    f += pill(x, y + 6.5, ws[i], 11, i === sel);
    f += bar(x + 5, y + 10.6, ws[i] - 10, 2.8, i === sel ? SOFT : FILL);
  });
  return doc(uid, label, b, f);
}

function L4(uid, label, ic, o) {
  let b = panel(uid, 22, 116, 8, null, 'fade', false, 'none');
  b += cluster(41, 66, BRAND.slice(0, 4));
  b += rule(22, 138, 82);
  for (let i = 0; i < 3; i++) {
    const y = 90 + i * 16;
    b += avatar(o, 32, y - 5.5, 11);
    b += bar(48, y - 2.2, 54, 4.4);
    b += check(119, y - 4.5, 9, i === 0 ? ACC : FILL);
  }
  const y = GEO.CARD_Y;
  let f = card(11, y, 138, 26, 9, uid);
  BRAND.slice(0, 4).forEach((c, i) => { f += tile(o, 26 + i * 23, y + 7.5, 12, 4, c); });
  f += vrule(119, y + 7, y + 19, 0.8) + slot(o, 'action', 'system.search', 128, y + 8, 10, SOFT);
  return doc(uid, label, b, f);
}

/* Narrow panel with a real header, chips on the diagonal. */
function L5(uid, label, ic, o) {
  let b = panel(uid, 28, 104, 8, null, 'fade', false, 'offset');
  b += bar(96, 20, 18, 4.6) + kebab(124, 22.5);   // answers the chip on the left
  b += rule(28, 132, 34, 0.5);
  for (let i = 0; i < o.rows; i++) {
    const y = 46 + i * 19;
    b += slot(o, 'row', 'system.book-open', 38, y, 12, SOFT);
    b += barpair(56, y - 0.5, 24, 52, 4, 5, 7.2);
  }
  const a = card(13, 12, 58, 21, 8, uid) + slot(o, 'feature', ic, 22, 17, 12) + bar(39, 20.4, 24, 4.6);
  const c = card(91, 94, 58, 21, 8, uid) + slot(o, 'second', 'system.stack', 100, 99, 12, SOFT) + bar(117, 102.4, 24, 4.6);
  return doc(uid, label, b, a + c);
}

/* Wide panel sized to hold its rows. Nothing spills. */
function L6(uid, label, ic, o) {
  let b = panel(uid, 13, 134, 8, null, 'fade', true, 'twin');
  for (let i = 0; i < 3; i++) {
    const y = 34 + i * 22;
    b += card(21, y, 118, 18, 6, uid, i === 0);
    b += tile(o, 26, y + 3, 12, 4, BRAND[i]);
    b += bar(44, y + 6.6, 22, 4.4);
    b += vrule(73, y + 4, y + 14, 0.7);
    b += bar(80, y + 6.6, 24, 4.4);
    b += vrule(110, y + 4, y + 14, 0.7);
    b += bar(117, y + 6.6, 12, 4.4);
    b += kebab(134, y + 9);
  }
  return doc(uid, label, b, '');
}

/* Contained panel. The raised card breaks its top edge. */
function L7(uid, label, ic, o) {
  let b = panel(uid, 16, 128, 44, 92, 'contained', false, 'none');
  [22, 92].forEach((x, i) => {
    b += card(x, 54, 46, 50, 9, uid, false);
    b += `<circle cx="${x + 23}" cy="70" r="9.5" fill="${BRAND[i + 1]}" opacity="0.3"/>`;
    b += avatar(o, x + 17, 64, 12);
    b += bar(x + 11, 86, 24, 4.2) + bar(x + 8, 93, 30, 4.2);
  });
  b += bar(48, 112, 64, 5) + bar(58, 121, 44, 4.4);
  let mid = card(55, 32, 50, 60, 11, uid);
  mid += `<circle cx="80" cy="52" r="12" fill="${ACC}" opacity="0.14"/>`;
  mid += avatar(o, 72.5, 44.5, 15, ACC);
  mid += bar(65, 70, 30, 4.8) + bar(61, 78.5, 38, 4.8);
  return doc(uid, label, b, mid);
}

/* Contained, almost no chrome. The cards are the whole idea. */
function L8(uid, label, ic, o) {
  let b = panel(uid, 26, 108, 30, 100, 'contained', false, 'offset');
  b += card(38, 80, 92, 32, 10, uid, false);
  b += `<circle cx="53" cy="96" r="9.5" fill="${BRAND[1]}" opacity="0.8"/>`;
  b += bar(69, 89, 34, 4.8) + bar(69, 98.5, 50, 5.4);
  let f = card(16, 44, 112, 34, 10, uid);
  f += `<circle cx="33" cy="61" r="10" fill="${BRAND[0]}" opacity="0.8"/>`;
  f += bar(50, 53, 40, 5) + bar(50, 63, 62, 5.6);
  return doc(uid, label, b, f);
}

/* No header. The hub is the floating element: when a feature is about one thing
   everything else connects to, a title bar above it is noise. */
function L9(uid, label, ic, o) {
  let b = panel(uid, 21, 118, 8, null, 'fade', false, 'plate');
  [[28, 34], [28, 82], [112, 34], [112, 82]].forEach(([x, y]) => {
    const sx = x < 80 ? 44 : 112;
    const ex = x < 80 ? 63 : 97;
    const cx = (sx + ex) / 2;
    b += `<path d="M${x < 80 ? sx : x} ${y + 8}C${cx} ${y + 8} ${cx} 63 ${x < 80 ? ex : 97} 63" ` +
      `fill="none" stroke="${LINE}" stroke-width="${SW}" stroke-dasharray="2.4 3" stroke-linecap="round"/>`;
    b += tile(o, x, y);
  });
  b += bar(52, 104, 56, 5) + bar(62, 114, 36, 4.4);
  const hub = card(63, 46, 34, 34, 11, uid) + slot(o, 'feature', ic, 71, 54, 18);
  return doc(uid, label, b, hub);
}

/* A corner chip, not a title bar. The column icons already occupy the right of
   the header band, so a full-width float would fight them. */
function L10(uid, label, ic, o) {
  let b = panel(uid, 21, 118, 8, null, 'fade', false, 'none');
  const cols = [92, 108, 124];
  [84, 100, 116, 132].forEach((x) => { b += vrule(x, 48, 124, 0.55); });
  ['col1', 'col2', 'col3'].forEach((key, i) => {
    b += slot(o, key, ['system.book-open', 'system.code', 'system.shield-checkmark'][i], cols[i] - 6, 49.5, 12, SOFT);
  });
  b += rule(30, 132, 66);
  [[1, 1, 1], [1, 1, 0], [1, 0, 0], [0, 1, 0]].forEach((cells, r) => {
    const y = 76 + r * 13;
    b += avatar(o, 31, y - 6.5, 13) + bar(48, y - 2.5, 26, 5);
    cols.forEach((x, i) => { b += dot(x, y, 3, !!cells[i]); });
  });
  const chip = card(13, 16, 62, 22, 8, uid) + slot(o, 'feature', ic, 22, 21, 12) + bar(39, 24.4, 26, 4.6);
  return doc(uid, label, b, chip);
}

/* Narrow panel, narrow float. A full-width bar over a single column of events
   reads as a header bolted onto the wrong shape. */
function L11(uid, label, ic, o) {
  let b = panel(uid, 28, 104, 8, null, 'fade', false, 'offset');
  const ys = [];
  for (let i = 0; i < o.rows; i++) ys.push(56 + i * 24);
  b += rail(44, ys);
  ys.forEach((y) => { b += barpair(58, y - 7, 22, 50, 4.2, 5.2, 7.4); });
  b += bar(102, 22, 18, 4.6) + kebab(124, 24.5);   // answers the chip on the left
  const chip = card(18, 14, 74, 22, 8, uid) + slot(o, 'feature', ic, 27, 19, 12) + bar(44, 22.4, 34, 4.6);
  return doc(uid, label, b, chip);
}

function L12(uid, label, ic, o) {
  let b = panel(uid, 22, 116, 30, 100, 'contained', false, 'plate');
  const cw = 44, lx = 28, rx = 88;   // a gap of 16 leaves the arrow room to breathe
  [[lx, false], [rx, true]].forEach(([x, done]) => {
    b += card(x, 62, cw, 44, 8, uid, false);
    b += bar(x + 8, 71, 26, 4.6) + bar(x + 8, 80, 18, 4.6);
    b += done ? check(x + 7, 89) : dot(x + 10.5, 93.5, 3.2, false);
    padded(62, 44, 71, 98, 'split card');
  });
  b += slot(o, 'action', 'system.arrow-right', fits(lx + cw, rx, 12, 'flow arrow'), 78, 12, SOFT);
  b += bar(56, 116, 48, 4.6);
  return doc(uid, label, b, medallion(uid, o, ic, 80, 37, 17));
}

